MSP2_ADSB_VEHICLE: Final[int] = 8339

class MSP2_ADSB_VEHICLE_request_t(BaseModel):
    """Retrieves a single tracked ADSB (Automatic Dependent Surveillance-Broadcast) vehicle by slot index. Intended for polling one slot at a time: query `MSP2_ADSB_VEHICLE_COUNT` for the iteration bound, then request indices `0 .. count-1`, skipping slots with `ttl == 0`, and identify each aircraft by its `icao`. See `adsbVehicle_t` / `adsbVehicleValues_t` in `io/adsb.h`."""

    model_config = ConfigDict(populate_by_name=True)

    index: uint8 = Field(description='Slot index to read, `0 .. (MSP2_ADSB_VEHICLE_COUNT - 1)`. WARNING: this is an iteration cursor over fixed slots, NOT a stable identifier. The same index may return a different aircraft (or an empty slot) on a later poll. Always identify the aircraft by the `icao` field in the reply; never cache or correlate data by index. Returns an error result if the index is out of range.')


class MSP2_ADSB_VEHICLE_reply_t(BaseModel):
    """Retrieves a single tracked ADSB (Automatic Dependent Surveillance-Broadcast) vehicle by slot index. Intended for polling one slot at a time: query `MSP2_ADSB_VEHICLE_COUNT` for the iteration bound, then request indices `0 .. count-1`, skipping slots with `ttl == 0`, and identify each aircraft by its `icao`. See `adsbVehicle_t` / `adsbVehicleValues_t` in `io/adsb.h`."""

    model_config = ConfigDict(populate_by_name=True)

    icao: uint32 = Field(description='ICAO 24-bit address (`vehicleValues.icao`). This is the stable per-aircraft identifier; use it to correlate replies, not the request index. An empty slot reports `icao == 0` and `ttl == 0`.')
    lat: int32 = Field(description='Latitude (`vehicleValues.gps.lat`). [1e-7 deg]')
    lon: int32 = Field(description='Longitude (`vehicleValues.gps.lon`). [1e-7 deg]')
    alt: int32 = Field(description='Altitude above sea level (`vehicleValues.alt`). [cm]')
    heading: uint16 = Field(description='Course over ground at full resolution (`vehicleValues.heading`). Unlike `MSP2_ADSB_VEHICLE_LIST`, this is in centidegrees, not whole degrees. [1e-2 deg]')
    horVelocity: uint16 = Field(description='Horizontal (ground) speed (`vehicleValues.horVelocity`). Not present in `MSP2_ADSB_VEHICLE_LIST`. [cm/s]')
    tslc: uint8 = Field(description='Time since last communication (`vehicleValues.tslc`). [s]')
    emitterType: uint8 = Field(description='Emitter category (`vehicleValues.emitterType`).')
    ttl: uint8 = Field(description='Remaining time-to-live for this slot (`adsbVehicle->ttl`). `ttl == 0` means the slot is empty/expired and its contents are stale; skip such entries. [s]')
    callsign: str = Field(description='Fixed-length callsign (`vehicleValues.callsign`), padded with NULs if shorter.')


